"""CamoAccessoryBones.lua: which skeleton bones each accessory mesh's skin uses, for EVERY accessory in the game.

Where a skinned socket object ends up on screen is not its transform -- it spawns at the origin and its SKIN puts
it on the bones it is weighted to. The view needs that to frame the piece (and to say where it is), and the
answer is a property of the MESH, so it is read from the meshes themselves rather than decided per accessory:

    RimeREPL <script>      mount_game + mesh_roundtrip <mesh> for every accessory mesh of the catalogue
    this                   its "LOD[0] BONES: ... boneIndexArray=[...]" lines -> Data/CamoAccessoryBones.lua

The indices Rime prints are 0-based into WeaponSke01; the view indexes mesh3pTransforms 1-based, so they are
written +1 here (17 -> 18 = Wep_Bipod1). Rigid meshes have no bone list and are simply not in the table: the
view frames those by their own transform.

usage: python make_accessory_bones.py <bones.log> [<out.lua>]
"""
import io
import re
import sys

LOG = sys.argv[1]
OUT = sys.argv[2] if len(sys.argv) > 2 else r"F:\Desktop\Venice Unleashed\Rime-src\RimeUIEditor\Data\CamoAccessoryBones.lua"

BONE_NAMES = ["exportAnimation", "Wep_Root", "Wep_Extra1", "Wep_Trigger", "Wep_Slide", "Wep_Grenade1", "Wep_Grenade2",
              "Wep_Mag", "Wep_Mag_Ammo", "Wep_Physic1", "Wep_Physic2", "Wep_Physic3", "Wep_Belt1", "Wep_Belt2",
              "Wep_Belt3", "Wep_Belt4", "Wep_Belt5", "Wep_Bipod1", "Wep_Bipod2", "Wep_Bipod3", "IK_Joint_LeftHand",
              "IK_Joint_RightHand", "Wep_Extra2", "Wep_Extra3", "Wep_Aim"]

mesh, skinned, bones = None, False, {}
for line in io.open(LOG, encoding="utf-8", newline="").read().splitlines():
    header = re.match(r"\[mesh_roundtrip\] (\S+): .*Type=MeshType_(\w+)", line)
    if header:
        mesh, skinned = header.group(1).lower(), header.group(2) == "Skinned"
        continue

    found = re.search(r"LOD\[0\] BONES: partCount=\d+ boneIndexArray=\[([0-9,\s]*)\]", line)
    if found and mesh is not None and skinned and mesh not in bones:
        bones[mesh] = [int(n) + 1 for n in found.group(1).split(",") if n.strip() != ""]

if not bones:
    print("FAIL: no skinned mesh with a bone list in %s" % LOG)
    sys.exit(1)

lines = [
    "-- GENERATED by External/keku/make_accessory_bones.py from Rime's mesh_roundtrip -- do not edit by hand.",
    "--",
    "-- The skeleton bones (1-based into weaponStates[1].mesh3pTransforms, WeaponSke01's order) each accessory mesh's",
    "-- skin is weighted to. A skinned socket object spawns at the origin and its skin puts it on these, so this is",
    "-- what says where the piece actually is -- the view frames it there. Rigid meshes are not listed: they carry",
    "-- their own transform.",
    "return {",
]
for mesh in sorted(bones):
    named = ", ".join(BONE_NAMES[i - 1] for i in bones[mesh] if 1 <= i <= len(BONE_NAMES))
    lines.append('\t["%s"] = { %s },%s' % (mesh, ", ".join(str(i) for i in bones[mesh]),
                                           "   -- " + named if named else ""))
lines.append("}")

io.open(OUT, "w", encoding="utf-8", newline="\r\n").write("\n".join(lines) + "\n")

counts = {}
for mesh, ids in bones.items():
    counts[tuple(ids)] = counts.get(tuple(ids), 0) + 1

print("%d skinned accessory mesh(es) -> %s" % (len(bones), OUT))
for ids, n in sorted(counts.items(), key=lambda kv: -kv[1]):
    print("   %-16s %d mesh(es)  [%s]" % (str(list(ids)), n,
                                          ", ".join(BONE_NAMES[i - 1] for i in ids if 1 <= i <= len(BONE_NAMES))))
